{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Replacing § 49-13-108(b)(5)(E), the bill permits a commission-authorized public charter school and the local board of education of the LEA where the school is located, notwithstanding subdivision (b)(5)(D), to agree mutually in writing within 30 calendar days of authorization that the local board will be the school's authorizer and LEA. The local board must assume the charter agreement's rights and responsibilities. This option does not apply to a school whose charter agreement was renewed on appeal by the commission.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "mutually agree in writing that the local board of education will be the"
    },
    {
      "id": "P2",
      "proposition": "The charter agreement under the local-board transfer provision must be filed with the commission in the manner the commission prescribes.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "The charter\n\n agreement must be filed with the commission in a manner prescribed by the\n\n commission."
    },
    {
      "id": "P3",
      "proposition": "In § 49-13-110(b)(1), the bill replaces \"A charter agreement\" with \"An initial charter agreement\".",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "deleting \"A charter agreement\" and substituting \"An initial charter agreement\"."
    },
    {
      "id": "P4",
      "proposition": "Replacing §§ 49-13-110(c) and 49-13-121(g), the bill requires a renewed charter agreement to have a term of 10 academic years when the public charter school's renewal application is approved by a local board of education.",
      "importance": "core",
      "section": "SECTIONS 3–4",
      "source_quote": "then the term of the renewed charter agreement must be for\n\n ten (10) academic years."
    },
    {
      "id": "P5",
      "proposition": "Replacing §§ 49-13-110(c) and 49-13-121(g), the bill requires a renewed charter agreement to have a term of at least five but no more than 10 academic years when the public charter school's renewal application is approved by the commission, with the term determined by commission resolution.",
      "importance": "core",
      "section": "SECTIONS 3–4",
      "source_quote": "as determined by resolution of the commission."
    },
    {
      "id": "P6",
      "proposition": "In §§ 49-13-121(f)(3) and 49-13-121(l), the bill deletes the introductory language \"Notwithstanding subsection (g), the first sentence of § 49-13-110(b), and § 49-13-110(c), if\" and substitutes \"If\".",
      "importance": "supporting",
      "section": "SECTIONS 5–6",
      "source_quote": "and substituting \"If\"."
    },
    {
      "id": "P7",
      "proposition": "The act takes effect upon becoming a law.",
      "importance": "supporting",
      "section": "SECTION 7",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it."
    }
  ]
}
